import unittest

from tools.skeleton_ping import ping


class SkeletonPingTests(unittest.TestCase):
    def test_ping_is_deterministic(self):
        self.assertEqual(ping("tracer"), "pong:tracer")

    def test_ping_defaults_to_orbita(self):
        self.assertEqual(ping(), "pong:orbita")
